NEW_FILES = {'tests/test_bank_finish.py': '"""A bank\'s public room is panelled below a chair rail, and its glass front is a storefront (0.285.0, the factory\'s\nroadmap 321).\n\nThe walker\'s bank comps (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md) put dark wood panelling under white or\nbeige walls, and a tall window to the street. 0.282.0 plastered a bank\'s walls floor to ceiling, and its `glass` front\nwas built as Zoo\'s opaque `glass_facade` slab: a wall of dark bars inside, a blank one outside (the factory\'s\ndocs/findings/bank_interior/, frames 09, 10 and 13).\n\nFAILS ON 0.284.0: no bank carries a panelling slot, and no bank\'s front is tagged a storefront.\n"""\nimport json\nimport os\n\nimport pytest\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nBUILD = os.path.join(HERE, "build")\n#: the banks whose public room has a wall that is not glass, and the two whose front is `glass`\nPANELLED = ("bank_branch_a02", "bank_branch_a03", "bank_job")\nGLASS_FRONTS = ("bank_branch_a02", "bank_branch_a03", "bank_job")\n\nSHEET_T = 0.006\nRAIL_T = 0.009\n#: `level_design._WALL_PIECE_AIR`: a wall piece\'s back stands this far off the face\nAIR = 0.01\n\n\ndef _slots(name):\n    p = os.path.join(BUILD, name + ".slots.json")\n    if not os.path.exists(p):\n        pytest.skip("no build of %s" % name)\n    return json.load(open(p, encoding="utf-8"))["slots"]\n\n\ndef _gameplay(name):\n    return json.load(open(os.path.join(BUILD, name + ".gameplay.json"), encoding="utf-8"))\n\n\ndef _dado(s):\n    return "_seg_dado" in s["slot_id"]\n\n\ndef _box(s):\n    """A slot\'s world box (x0, y0, z0, x1, y1, z1): its dims turned by its facing, as `_record_wall_slot` wrote them."""\n    d = s["fit"]["dims"]\n    t = s["transform"]["translation"]\n    along_x = s.get("facing") in ("N", "S", "X")\n    w = (d[0], d[1]) if along_x else (d[1], d[0])\n    return (t[0] - w[0] / 2, t[1] - w[1] / 2, t[2] - d[2] / 2,\n            t[0] + w[0] / 2, t[1] + w[1] / 2, t[2] + d[2] / 2)\n\n\ndef test_a_banks_public_room_is_panelled_below_a_rail():\n    for name in PANELLED:\n        sl = _slots(name)\n        dado = [s for s in sl if _dado(s)]\n        assert dado, name\n        for s in dado:\n            assert s["role"] == "wall" and s["size_mod"] == "end", s["slot_id"]\n            assert s["material"] == "wood_panel", s["slot_id"]\n            assert s["fit"]["dims"][1] in (SHEET_T, RAIL_T), s["slot_id"]\n            # the rail\'s top is the panelling\'s, 0.9 m over the wall\'s foot or a sill\n            assert s["fit"]["dims"][2] <= 0.9, s["slot_id"]\n        assert {s["fit"]["dims"][1] for s in dado} == {SHEET_T, RAIL_T}, name\n\n\ndef test_the_panelling_stands_on_a_public_rooms_edge_inside_the_wall_pieces_air():\n    for name in PANELLED:\n        g = _gameplay(name)\n        public = [r for r in g["rooms"] if r.get("role") == "public_entry"]\n        for s in (s for s in _slots(name) if _dado(s)):\n            x0, y0, z0, x1, y1, z1 = _box(s)\n            assert max(x1 - x0, y1 - y0) > 0.05\n            assert min(x1 - x0, y1 - y0) < AIR, s["slot_id"]\n            ok = False\n            for r in public:\n                bx0, by0, bx1, by1 = r["bounds"]\n                if bx0 - 0.2 <= x0 and x1 <= bx1 + 0.2 and by0 - 0.2 <= y0 and y1 <= by1 + 0.2:\n                    ok = True\n            assert ok, (name, s["slot_id"])\n\n\ndef test_no_two_pieces_of_panelling_overlap():\n    for name in PANELLED:\n        boxes = [(s["slot_id"], _box(s)) for s in _slots(name) if _dado(s)]\n        for i, (na, a) in enumerate(boxes):\n            for nb, b in boxes[i + 1:]:\n                ov = [min(a[k + 3], b[k + 3]) - max(a[k], b[k]) for k in range(3)]\n                assert min(ov) <= 1e-6, (name, na, nb, ov)\n\n\ndef test_no_other_building_is_panelled():\n    for name in ("deli_a03", "pharmacy_a01", "supermarket_a01", "credit_union_a01"):\n        assert not [s for s in _slots(name) if _dado(s)], name\n\n\ndef test_a_banks_glass_front_is_a_storefront_and_nothing_else_moved():\n    for name in GLASS_FRONTS:\n        front = [s for s in _slots(name) if s.get("glazing") == "storefront"]\n        assert front, name\n        assert {s["role"] for s in front} <= {"wall", "doorway"}, name\n        g = _gameplay(name)\n        public = {r["id"] for r in g["rooms"] if r.get("role") == "public_entry"}\n        assert public\n    # a pharmacy\'s and a supermarket\'s glass fronts are the walker\'s call, and stay opaque\n    for name in ("pharmacy_a01", "supermarket_a01"):\n        assert not [s for s in _slots(name) if s.get("glazing") == "storefront"], name\n\n\ndef test_a_vaults_fixtures_ask_for_what_they_are_made_of():\n    """The library\'s deposit-box walls and vault doors took their wall\'s `concrete`; they ask their species for the\n    spec\'s own `metal`, which is not what either is made of, so each takes its own (`FIXTURE_OPENINGS`)."""\n    import glob\n    seen = {"safe_deposit_boxes": 0, "vault_door": 0}\n    want = {"safe_deposit_boxes": "metal_bare", "vault_door": "metal_painted"}\n    for p in glob.glob(os.path.join(BUILD, "*.slots.json")):\n        for s in json.load(open(p, encoding="utf-8"))["slots"]:\n            if s["role"] in want:\n                assert s["material"] == want[s["role"]], (os.path.basename(p), s["slot_id"], s["material"])\n                seen[s["role"]] += 1\n    assert seen["safe_deposit_boxes"] >= 5 and seen["vault_door"] >= 3, seen\n'}
CHANGELOG = '## [0.285.0] - a bank\'s public room panelled below a chair rail, and its glass front a storefront\n\nThe walker, of the bank\'s frames: "do the interiors look really good?", then "hold the release, do the interior pass\nfirst". The comps (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md) put dark wood panelling under white or beige\nwalls and a tall window to the street. On 0.284.0 a bank\'s lobby was plaster floor to ceiling, and its front a wall of\ndark bars (docs/findings/bank_interior/, frames 09, 10 and 13).\n\n### Added\n- **A bank\'s public room is panelled below a chair rail** (`_dados`, `BANK_DADO`).\n  - On the room face of every wall and window slot on a bank\'s public room\'s edge (`lights.bank_public`): a sheet of\n    `wood_panel` from the wall\'s foot, `BANK_DADO_T` (6 mm, 1/4 in sheet) proud, under a rail `BANK_RAIL_H` (5 cm) high\n    and `BANK_RAIL_T` (9 mm) proud. The rail\'s top is `BANK_DADO_TOP` (0.9 m, about 36 in) over the foot, or a window\'s\n    sill where that is lower.\n  - Both stay inside `level_design._WALL_PIECE_AIR` (0.01 m), so a chair or an ATM against the wall still clears them,\n    and both are four or more times `zfight_gate.TOL` off the face.\n  - Each is a `wallEnd` slot -- the unit box Deli Counter scales -- named under its wall, so no module is added to a\n    kit and the export\'s merge (Level Factory 0.223.0) folds a wall side\'s panelling into one mesh. No collision.\n  - A door, a breach, the teller line and glass take none. Where two walls meet, the one along X owns the corner.\n  - The card shop\'s note that a dado "is not built and it is not pretended" stands: its panelling is still whole\n    partitions. This is the geometry it asked for, so far a bank\'s.\n\n### Changed\n- **A bank\'s glass front is a storefront** (`bank_front`, `BANK_FRONT_MATERIALS`).\n  - The library\'s banks name their front `glass`, which Zoo builds as a solid `glass_facade` slab (`OPAQUE_FOR`).\n    A full wall or door slot of it in front of a bank\'s public room is tagged `glazing: "storefront"`, the shop-front\n    rule the walker set on 2026-09-28: Zoo\'s aluminium storefront, see-through, its collider unchanged.\n  - Not the bank\'s other rooms, and not the library\'s other 49 `glass` walls (pharmacies, supermarkets, pawn shops,\n    clinics, offices): the walker\'s call.\n\n### Fixed\n- **A vault\'s fixtures ask for what they are made of** (`FIXTURE_OPENINGS`).\n  - An opening slot took its WALL\'s material, so the library\'s deposit-box walls and vault doors asked Zoo for\n    `concrete`, which Zoo builds whatever a species offers, and which the vault door\'s genome even offers.\n  - A vault door\'s and a deposit wall\'s slot asks its species for the opening\'s own material (the spec\'s `metal`), by\n    0.284.0\'s `prop_species.material_for`: the deposit boxes take bare steel (Zoo 1.140.0\'s), the door painted steel.\n    `SPECIES_MATERIALS` mirrors both. A doorway, a window and a breach are the wall and keep it.\n\n### Measured, the library built\n- Every bank is panelled: `bank_branch_a02` 51.3 m of sheet in 58 slots, `a03` 49.4 m, `a04` 108.8 m, `bank_job`\n  51.3 m, `bank_tower_a01` to `a03` 96.9-102.2 m. No other building.\n- Three fronts are storefronts, the three whose front is `glass`: `bank_branch_a02` 10 slots, `a03` 13, `bank_job` 10.\n- The five deposit-box walls are `metal_bare`, the three vault doors `metal_painted`, where all eight were `concrete`.\n- Nothing else moved: every building\'s slots are 0.284.0\'s but for its panelling.\n\n### Tests\n- `tests/test_bank_finish.py` (new; fails on 0.284.0): a bank\'s public room panelled below a rail, every piece on its\n  edge and inside the wall piece\'s air, no two overlapping, no other building panelled, the three glass fronts\n  storefronts and a pharmacy\'s and a supermarket\'s not, and every vault fixture on its own steel.\n- `tests/test_storefront_glazing.py`: the three bank fronts leave its opaque list; every tower\'s glass stays opaque.\n\n'
